  4446  static void
  4447  remove_from_list(Node* prev, Node* a)
  4448  {
  4449    if (NODE_CDR(prev) != a) return ;
  4450
  4451    NODE_CDR(prev) = NODE_CDR(a);
  4452    NODE_CDR(a) = NULL_NODE;
  4453  }
  4454
  4455  static int
  4456  reduce_string_list(Node* node)
  4457  {
  4458    int r = 0;
  4459
  4460    switch (NODE_TYPE(node)) {
  4461    case NODE_LIST:
  4462      {
  4463        Node* prev;
  4464        Node* curr;
  4465        Node* prev_node;
  4466        Node* next_node;
  4467
  4468        prev = NULL_NODE;
  4469        do {
  4470          next_node = NODE_CDR(node);
  4471          curr = NODE_CAR(node);
  4472          if (NODE_TYPE(curr) == NODE_STRING) {
  4473            if (IS_NULL(prev)
  4474                || STR_(curr)->flag  != STR_(prev)->flag
  4475                || NODE_STATUS(curr) != NODE_STATUS(prev)) {
  4476              prev = curr;
  4477              prev_node = node;
  4478            }
  4479            else {
  4480              r = node_str_node_cat(prev, curr);
  4481              if (r != 0) return r;
  4482              remove_from_list(prev_node, node);
  4483              onig_node_free(node);
  4484            }
  4485          }
  4486          else {
  4487            prev = NULL_NODE;
  4488            prev_node = node;
  4489          }
  4490
  4491          node = next_node;
  4492        } while (r == 0 && IS_NOT_NULL(node));
  4493      }
  4494      break;
  4495
  4496    case NODE_ALT:
  4497      do {
  4498        r = reduce_string_list(NODE_CAR(node));
  4499      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  4500      break;
  4501
  4502    case NODE_ANCHOR:
  4503      if (IS_NULL(NODE_BODY(node)))
  4504        break;
  4505      /* fall */
  4506    case NODE_QUANT:
  4507      r = reduce_string_list(NODE_BODY(node));
  4508      break;
  4509
  4510    case NODE_BAG:
  4511      {
  4512        BagNode* en = BAG_(node);
  4513
  4514        r = reduce_string_list(NODE_BODY(node));
  4515        if (r != 0) return r;
  4516
  4517        if (en->type == BAG_IF_ELSE) {
  4518          if (IS_NOT_NULL(en->te.Then)) {
  4519            r = reduce_string_list(en->te.Then);
  4520            if (r != 0) return r;
  4521          }
  4522          if (IS_NOT_NULL(en->te.Else)) {
  4523            r = reduce_string_list(en->te.Else);
  4524            if (r != 0) return r;
  4525          }
  4526        }
  4527      }
  4528      break;
  4529
  4530    default:
  4531      break;
  4532    }
  4533
  4534    return r;
  4535  }
